from typing import List, Tuple
import heapq

def dijkstra(graph: List[List[Tuple[int, int]]], start: int) -> List[int]:
    n = len(graph)
    dist = [float('inf')] * n
    dist[start] = 0
    pq = [(0, start)]

    while pq:
        current_dist, u = heapq.heappop(pq)
        if current_dist > dist[u]:
            continue
        for v, weight in graph[u]:
            distance = current_dist + weight
            if distance < dist[v]:
                dist[v] = distance
                heapq.heappush(pq, (distance, v))

    return dist

def find(parent, i):
    if parent[i] == i:
        return i
    return find(parent, parent[i])

def union(parent, rank, x, y):
    rootX = find(parent, x)
    rootY = find(parent, y)

    if rootX != rootY:
        if rank[rootX] > rank[rootY]:
            parent[rootY] = rootX
        elif rank[rootX] < rank[rootY]:
            parent[rootX] = rootY
        else:
            parent[rootY] = rootX
            rank[rootX] += 1

def solve(n: int, m: int, edges: List[Tuple[int, int]], attacked_cities: List[int]) -> Tuple[int, int]:
    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u-1].append((v-1, 1))
        graph[v-1].append((u-1, 1))

    attacked_set = set(attacked_cities)
    parent = list(range(n))
    rank = [0] * n

    for u, v in edges:
        u -= 1
        v -= 1
        if u in attacked_set and v in attacked_set:
            union(parent, rank, u, v)

    root = find(parent, attacked_cities[0])
    if not all(find(parent, city) == root for city in attacked_cities):
        return None, None

    min_time = float('inf')
    best_city = -1

    for city in attacked_cities:
        dist = dijkstra(graph, city-1)
        max_distance = max(dist[city-1] for city in attacked_cities if dist[city-1] != float('inf'))
        if max_distance < min_time:
            min_time = max_distance
            best_city = city

    return best_city, min_time

